import pytest

from sales_dashboard.report import campaign_summary, top_converting_groups


def test_campaign_summary_pooled_rounded_rate_and_calendar_window():
    groups = {
        "small": [{"id": "a", "day": 1, "converted": True}],
        "large": [
            {"id": "b", "day": 4, "converted": True},
            {"id": "c", "day": 6, "converted": False},
            {"id": "d", "day": 1, "converted": None},
            {"id": "e", "day": 4, "converted": False},
            {"id": "f", "day": 4, "converted": False},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary(groups, 20)["recent"] == 2
    assert campaign_summary(groups, 0)["recent"] == 0


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 7) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_orders_ties_and_excludes_empty_groups():
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "empty": [],
        "best": [{"converted": True}],
        "a": [{"converted": False}, {"converted": True}],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 3) == ["best", "a", "z"]
    assert top_converting_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({}, 3) == []
    assert top_converting_groups({"empty": []}, 3) == []

